def complexPrimitiveKernel (a : ℤ) (q n m : ℕ) : ℂ :=
  (if (((n * m : ℕ) : ℤ) % (q : ℤ) = a % (q : ℤ)) then 1 else 0) -
    (if (n * m).Coprime q then 1 else 0) / (Nat.totient q : ℂ)

def MediumAtom.complexDispersionW (d : MediumAtom) (S : Finset ℕ)
    (w : ℕ → ℝ) : ℝ :=
  ∑ n ∈ S, w n * ‖d.complexProgressionRow n‖ ^ 2

def MediumAtom.complexDispersionU (d : MediumAtom) (S : Finset ℕ)
    (w : ℕ → ℝ) : ℝ :=
  ∑ n ∈ S, w n * ‖d.complexPrincipalRow n‖ ^ 2

def centeredResidueIndicator (q : ℕ) [NeZero q] (a z : ZMod q) : ℂ :=
  (if z = a then 1 else 0) -
    (if IsUnit z then 1 else 0) / (Nat.totient q : ℂ)

def centeredAdditiveCoefficient (q : ℕ) [NeZero q] (a h : ZMod q) : ℂ :=
  ZMod.stdAddChar (-h * a) -
    primitiveAdditiveCoefficient q h / (Nat.totient q : ℂ)

def betaCoprimeAPDiscrepancy (N : Finset ℕ) (β : ℕ → ℝ) (d h b : ℕ) : ℝ :=
  (∑ n ∈ N, if n.Coprime h ∧ Nat.ModEq d n b then β n else 0) -
    coprimeMass N β (d * h) / (d.totient : ℝ)

def uModulusCoefficient (N : Finset ℕ) (β c : ℕ → ℝ) (q r : ℕ) : ℝ :=
  (c q * c r / ((q.totient : ℝ) * (r.totient : ℝ))) *
    coprimeMass N β q * coprimeMass N β r
